{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-wakatime",
  "repository": {
    "type": "git",
    "url": "https://github.com/angristan/opencode-wakatime.git"
  },
  "version": "1.4.0",
  "description": "WakaTime plugin for OpenCode - Track AI coding activity and time spent",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js"
    }
  },
  "files": [
    "dist",
    "bin"
  ],
  "bin": {
    "opencode-wakatime": "bin/cli.js"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json && npm run bundle",
    "bundle": "node scripts/bundle.js",
    "typecheck": "tsc --noEmit",
    "lint": "biome lint .",
    "format": "biome format .",
    "check": "biome check .",
    "test": "vitest",
    "test:run": "vitest run",
    "test:coverage": "vitest run --coverage",
    "prepublishOnly": "npm run build",
    "prepare": "husky"
  },
  "keywords": [
    "opencode",
    "wakatime",
    "time-tracking",
    "ai",
    "coding",
    "productivity"
  ],
  "author": "",
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@biomejs/biome": "2.4.8",
    "@commitlint/cli": "^20.0.0",
    "@commitlint/config-conventional": "^20.0.0",
    "@opencode-ai/plugin": "^1.0.0",
    "@semantic-release/changelog": "^6.0.3",
    "@semantic-release/git": "^10.0.1",
    "@types/node": "^25.0.3",
    "@vitest/coverage-v8": "^4.1.0",
    "conventional-changelog-conventionalcommits": "^9.3.1",
    "esbuild": "^0.27.2",
    "husky": "^9.1.7",
    "lint-staged": "^16.0.0",
    "semantic-release": "^25.0.9",
    "typescript": "^5.0.0",
    "vitest": "^4.1.0"
  },
  "lint-staged": {
    "*.{ts,js,json}": [
      "biome check --write"
    ]
  },
  "overrides": {
    "tar": ">=7.5.7"
  },
  "dependencies": {
    "jsonc-parser": "3.3.1"
  }
}
